from itertools import permutations

def solve():
    subjects = ['Math', 'Science', 'English', 'Art']
    forbidden = {
        'Math': {4},
        'Science': {1},
        'English': {5},
        'Art': {1, 3}
    }
    count = 0
    for perm in permutations(subjects):
        for extra_idx in range(4):
            lengths = [1, 1, 1, 1]
            lengths[extra_idx] = 2
            start = 1
            valid = True
            for i, subj in enumerate(perm):
                for p in range(start, start + lengths[i]):
                    if p in forbidden[subj]:
                        valid = False
                        break
                if not valid:
                    break
                start += lengths[i]
            if valid:
                count += 1
    print(f"Valid timetables: {count}")

if __name__ == "__main__":
    solve()

