from itertools import product

def count_paths(max_moves=None):
    count = 0
    for moves in product('RD', repeat=6):
        if max_moves is not None and len(moves) != max_moves:
            continue
        r = d = 0
        ok = True
        for m in moves:
            if m == 'R':
                r += 1
            else:
                d += 1
            if r > 2 or d > 2:
                ok = False
                break
        if ok and r == 2 and d == 2:
            count += 1
    return count

